solution.solution.cpp:
#include <cstddef>
#include <vector>

// Runs the program stored in memory, starting at cell 0 with register A at 0.
// Returns what register A holds when the machine stops.
int run(std::vector<int>& memory)
{
    int a{ 0 };
    std::size_t pc{ 0 };

    while (pc < memory.size())
    {
        const int instruction{ memory[pc] };                              // fetch
        ++pc;
        const int operation{ instruction / 100 };                         // decode
        const auto cell{ static_cast<std::size_t>(instruction % 100) };

        switch (operation)                                                // execute
        {
        case 1: a = memory[cell]; break;
        case 2: a += memory[cell]; break;
        case 3: a -= memory[cell]; break;
        case 4: memory[cell] = a; break;
        case 5: pc = cell; break;
        case 6: if (a == 0) pc = cell; break;
        default: return a;              // HALT, or a number that is not an instruction
        }
    }
    return a;
}

unitTests:
TEST("adds two numbers") {
    std::vector<int> memory{ 110, 211, 412, 0, 0, 0, 0, 0, 0, 0, 7, 5, 0 };
    CHECK_EQ(run(memory), 12);
    CHECK_EQ(memory[12], 12);
}
TEST("subtracts") {
    std::vector<int> memory{ 110, 311, 412, 0, 0, 0, 0, 0, 0, 0, 20, 8, 0 };
    CHECK_EQ(run(memory), 12);
}
TEST("counts down with a loop") {
    std::vector<int> memory{ 110, 605, 311, 410, 501, 0, 0, 0, 0, 0, 3, 1 };
    CHECK_EQ(run(memory), 0);
    CHECK_EQ(memory[10], 0);
}
TEST("multiplies by adding again and again") {
    std::vector<int> memory{ 111, 608, 313, 411, 112, 210, 412, 500, 0, 0, 4, 3, 0, 1 };
    run(memory);
    CHECK_EQ(memory[12], 12);
}
TEST("stops at HALT and does not run what follows it") {
    std::vector<int> memory{ 0, 410, 0, 0, 0, 0, 0, 0, 0, 0, 55 };
    run(memory);
    CHECK_EQ(memory[10], 55);
}
TEST("leaves the program itself untouched") {
    std::vector<int> memory{ 110, 211, 412, 0, 0, 0, 0, 0, 0, 0, 1, 2, 0 };
    run(memory);
    CHECK_EQ(memory[0], 110);
    CHECK_EQ(memory[1], 211);
}

